      SUBROUTINE DFOCU2CC     DERIVATIVE OF SECOND-ORDER TRANSFER MATRIX FOR A QUADRUPOLEC     WITH RESPECT TO MAGNETIC FIELD OR GRADIENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'R.CIN'      INCLUDE 'T.CIN'CC     LOCAL VARIABLESCCC----------------------------------------------------------      J = JQUAD      CS = R(J,J)      SN = R(J,J+1)      DCS = - L*SN*KVK      IF (KQ2 .NE. 0.0) THEN        DSN = ( - SN + L*CS)*KVK/KQ2      ELSE        DSN = 0.0      ENDIF      DCSP = - (SN + L*CS)*KVK      BLOB = 0.5*(L**2*CS + L*SN)*KVKC      TV(J,J+15) = BLOB      TV(J+1,J+16) = BLOB      IF (KQ2 .NE. 0.0) THEN        TV(J,J+16) = 0.5*(( - SN + L*CS)/KQ2 + L**2*SN)*KVK      ELSE        TV(J,J+16) = 0.0      ENDIF      TV(J+1,J+15) = 0.5*(SN + 3.0*L*CS     1             - KQ2*L**2*SN)*KVKC      TV(5,J*(J+1)/2) = - 0.25*(2.0*L*KVK + DCSP*CS     1                - KQ2*SN*DCS)      TV(5,J*(J+3)/2) = - 0.5*(- KQ2*DSN*SN + SN*DCSP)      TV(5,J*(J+3)/2+1) = - 0.25*(DCS*SN + CS*DSN)  100 RETURN      END